async function request(input:RequestInfo|URL,init:RequestInit={},timeout=45000){
  const controller=new AbortController(),timer=window.setTimeout(()=>controller.abort(),timeout);
  try{return await fetch(input,{...init,signal:controller.signal});}
  catch(e){if((e as Error).name==='AbortError')throw Error('İşlem zaman aşımına uğradı. Bağlantıyı kontrol edip tekrar deneyin.');throw e;}
  finally{window.clearTimeout(timer);}
}
