function change(next:Catalog){setData(next);setDirty(true);setNotice('');if(tab==='settings')setError('');}
async function save(next:Catalog=data!,label='İçerik güncellemesi',extra:any={}){
  if(saveInFlight.current){
    const message='Önce devam eden işlemin tamamlanmasını bekleyin.';
    setError(message);
    if(tab==='products')setProductFeedback({tone:'error',message});

    return false;
  }
  saveInFlight.current=true;setBusy(true);setError('');setNotice('');
  if(tab==='products')setProductFeedback({tone:'info',message:label+' işleniyor…'});

  try{
    next=validateCatalog(next);
    const response=await request('/api/catalog',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:next,revision,label,...extra})},45000);
    const result:any=await response.json().catch(()=>({}));
    if(!response.ok||result.ok===false)throw Error(typeof result.error==='string'&&result.error?result.error:
      response.status===401?'Oturum süresi doldu. Yeniden giriş yapın.':
      response.status===403?'Bu işlem için yetkiniz bulunmuyor.':
      response.status===409?'Veriler başka bir oturumda değişmiş. Yenileyip tekrar deneyin.':
      response.status===429?'Çok fazla istek gönderildi. Daha sonra tekrar deneyin.':
      'Kaydetme işlemi tamamlanamadı ('+response.status+').');
    setRevision(result.revision);
    setData(normalizeCatalog(result.data||next));
    setDirty(false);
    const message=label.replace(/[.!\s]+$/,'')+' — başarıyla kaydedildi ve yayınlandı.';
    setNotice(message);
    if(tab==='products')setProductFeedback({tone:'success',message});

    return true;
  }catch(e){
    const message=(e as Error).message||'İşlem tamamlanamadı.';
    setError(message);
    if(tab==='products')setProductFeedback({tone:'error',message});

    return false;
  }finally{saveInFlight.current=false;setBusy(false);}
}
async function upload(files:FileList|null,apply:(urls:string[])=>void,kind:'image'|'pdf'|'hero'='image'):Promise<string[]>{if(!files?.length)return[];setBusy(true);setError('');const urls:string[]=[],failures:string[]=[];try{for(const file of Array.from(files)){try{const f=new FormData();f.append('file',file);const r=await request('/api/upload?kind='+kind,{method:'POST',body:f},120000);const b:any=await r.json();if(!r.ok)throw Error(b.error);urls.push(b.url);}catch(e){failures.push(file.name+': '+(e as Error).message);}}if(urls.length)apply(urls);if(failures.length)setError(failures.join(' · '));if(urls.length)setNotice(urls.length+' dosya yüklendi'+(failures.length?' · '+failures.length+' dosya yüklenemedi.':'.'));return urls;}finally{setBusy(false);}}
async function uploadSettingAsset(files:FileList|null,key:'hero'|'headerImage',kind:'image'|'hero',label:string){if(!files?.length||!data)return;const urls=await upload(files,()=>{},kind);if(!urls[0])return;const next={...data,settings:{...data.settings,[key]:urls[0]}};if(await save(next,label))setNotice('Görsel yüklendi ve doğrudan yayınlandı.');}
function goTab(next:string){
  if(!tabs.some(([key])=>key===next))return;
  setNotice('');setError('');setProductFeedback(null);
  const url=new URL(window.location.href);
  url.pathname='/admin';
  url.searchParams.set('tab',next);
  if(window.location.pathname+window.location.search!==url.pathname+url.search)
    window.history.pushState({tab:next},'',url.pathname+url.search+url.hash);
  setTab(next);
}
