if(!data)return <div className={'load-state '+(error?'state-error':'state-loading')}><div className="state-panel"><span className="state-kicker">İNOKSKAR YÖNETİM</span><h1>{error?'Yönetim verileri yüklenemedi':'Yönetim paneli hazırlanıyor'}</h1><p>{error||'Ürünler, talepler ve yönetim verileri güvenli şekilde yükleniyor.'}</p>{error?<button className="button" onClick={load}>Tekrar dene</button>:<div className="state-skeleton" aria-hidden="true"><span/><span/><span/></div>}</div></div>;
const s=data.settings;const field=(key:keyof Catalog['settings'],value:any)=>change({...data,settings:{...s,[key]:value}});const visibleProducts=data.products.filter(p=>matchesProduct(p,query)&&(categoryFilter==='all'||descendants(data.categories,categoryFilter).includes(p.category)));
const inquiryNeedle=inquiryQuery.trim().toLocaleLowerCase('tr-TR'),inquiryPhone=normalizeInquiryPhone(inquiryQuery);const visibleInquiries=inquiries.filter(q=>{if(!inquiryNeedle)return true;let b:any={};try{b=JSON.parse(q.data||'{}');}catch{}const hay=[q.requestCode,q.id,b.name,b.email,b.contact,b.businessName,b.phone].map(x=>String(x||'').toLocaleLowerCase('tr-TR'));if(hay.some(x=>x.includes(inquiryNeedle)))return true;const storedPhone=normalizeInquiryPhone(b.phone);return inquiryPhone.length>=4&&storedPhone.includes(inquiryPhone);});
function pricePreview(){if(!selected.length){setError('Önce ürün seçin.');return;}if(!s.rate){setError('Önce Site ayarlarından euro/TL kurunu girin.');return;}if(!Number.isFinite(amount)||(mode==='percent'&&amount<-100)||(mode==='set'&&amount<0)){setError('Geçerli bir zam veya indirim tutarı girin.');return;}setPreview(data!.products.filter(p=>selected.includes(p.id)).map(p=>{const euro=mode==='percent'?p.euro*(1+amount/100):mode==='set'?amount:p.euro+amount;return {...p,euro:Math.round(Math.max(0,euro)*100)/100,tl:steppedPrice((Math.round(Math.max(0,euro)*100)/100)*s.rate,p.tl||undefined)};}));}
