async function refreshOfficialRate(){
  if(dirty){const message='Resmi kuru yenilemeden önce mevcut değişiklikleri kaydedin.';setError(message);return;}
  setBusy(true);setError('');setNotice('');

  try{
    const r=await request('/api/rate/refresh',{method:'POST'},45000);
    if(r.status===401){location.href='/login';return;}
    const b:any=await r.json().catch(()=>({}));
    if(!r.ok)throw Error(b.error||'Resmi kur alınamadı.');
    await load();
    const message='Resmî EUR/TL kuru güncellendi: '+Number(b.rate).toLocaleString('tr-TR',{minimumFractionDigits:4,maximumFractionDigits:4})+' TL'+(b.rateDate?' · Kur tarihi: '+new Date(b.rateDate+'T00:00:00').toLocaleDateString('tr-TR'):'')+'.';
    setNotice(message);
  }catch(e){
    const message=(e as Error).message||'Resmî kur güncellenemedi.';
    setError(message);
  }finally{setBusy(false);}
}
async function changeAdminPassword(e:FormEvent<HTMLFormElement>){
  e.preventDefault();
  if(busy)return;
  setError('');
  setNotice('');
  setPasswordFeedback(null);
  if(!currentPassword){
    setPasswordFeedback({tone:'error',message:'Mevcut şifrenizi girin.'});
    return;
  }
  if(newPassword.length<8||newPassword.length>128){
    setPasswordFeedback({tone:'error',message:'Yeni şifre 8 ile 128 karakter arasında olmalıdır.'});
    return;
  }
  if(newPassword!==confirmPassword){
    setPasswordFeedback({tone:'error',message:'Yeni şifre ile tekrarı aynı olmalıdır.'});
    return;
  }
  if(currentPassword===newPassword){
    setPasswordFeedback({tone:'error',message:'Yeni şifreniz mevcut şifrenizle aynı olamaz.'});
    return;
  }
  setBusy(true);
  setPasswordFeedback({tone:'info',message:'Şifre kontrol ediliyor…'});
  try{
    const response=await request('/api/admin/password',{
      method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({currentPassword,newPassword,confirmPassword})
    },45000);
    const result:any=await response.json().catch(()=>({}));
    if(!response.ok||result.ok!==true){
      const fallback=response.status===401?'Oturumunuz sona ermiş. Tekrar giriş yapın.':
        response.status===403?'Bu işlem için yetkiniz bulunmuyor.':
        response.status===429?'Çok fazla deneme yapıldı. Lütfen biraz sonra tekrar deneyin.':
        response.status>=500?'Sunucu şifre değişikliği işlemini tamamlayamadı. Lütfen tekrar deneyin.':
        'Şifre değiştirilemedi. Bilgileri kontrol edin.';
      throw Error(typeof result.error==='string'&&result.error?result.error:fallback);
    }
    setCurrentPassword('');
    setNewPassword('');
    setConfirmPassword('');
    setPasswordFeedback({tone:'success',message:'Şifreniz başarıyla değiştirildi. Güvenliğiniz için yeni şifrenizle giriş yapmanız gerekiyor. Giriş sayfasına yönlendiriliyorsunuz…'});
    window.setTimeout(()=>{window.location.assign('/login?reset=1');},1700);
  }catch(e){
    setPasswordFeedback({tone:'error',message:(e as Error).message||'Şifre değiştirilemedi. Lütfen tekrar deneyin.'});
  }finally{
    setBusy(false);
  }
}
async function deleteInquiry(id:string){setBusy(true);setError('');try{const r=await request('/api/inquiries/'+encodeURIComponent(id),{method:'DELETE'},45000);const b:any=await r.json().catch(()=>({}));if(!r.ok)throw Error(b.error||'Müşteri talebi silinemedi.');setInquiries(current=>current.filter(x=>x.id!==id));window.dispatchEvent(new Event('inokskar:inquiry-change'));setNotice('Müşteri talebi silindi.');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
